// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List API keys
	// (GET /api-keys)
	ListApiKeys(ctx context.Context, request ListApiKeysRequestObject) (ListApiKeysResponseObject, error)
	// Create an API key
	// (POST /api-keys)
	CreateApiKey(ctx context.Context, request CreateApiKeyRequestObject) (CreateApiKeyResponseObject, error)
	// Revoke an API key
	// (DELETE /api-keys/{id})
	RevokeApiKey(ctx context.Context, request RevokeApiKeyRequestObject) (RevokeApiKeyResponseObject, error)
	// Log in as the local admin
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Log out
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Current principal
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Available sign-in methods
	// (GET /auth/methods)
	GetAuthMethods(ctx context.Context, request GetAuthMethodsRequestObject) (GetAuthMethodsResponseObject, error)
	// Single sign-on callback
	// (GET /auth/oidc/callback)
	OidcCallback(ctx context.Context, request OidcCallbackRequestObject) (OidcCallbackResponseObject, error)
	// Start single sign-on
	// (GET /auth/oidc/start)
	StartOidcLogin(ctx context.Context, request StartOidcLoginRequestObject) (StartOidcLoginResponseObject, error)
	// List CA presets
	// (GET /meta/ca-presets)
	ListCaPresets(ctx context.Context, request ListCaPresetsRequestObject) (ListCaPresetsResponseObject, error)
	// List pluggable type schemas
	// (GET /meta/schemas)
	GetMetaSchemas(ctx context.Context, request GetMetaSchemasRequestObject) (GetMetaSchemasResponseObject, error)
	// List organizations
	// (GET /orgs)
	ListOrgs(ctx context.Context, request ListOrgsRequestObject) (ListOrgsResponseObject, error)
	// List ACME accounts
	// (GET /orgs/{orgId}/acme-accounts)
	ListAcmeAccounts(ctx context.Context, request ListAcmeAccountsRequestObject) (ListAcmeAccountsResponseObject, error)
	// Register an ACME account
	// (POST /orgs/{orgId}/acme-accounts)
	CreateAcmeAccount(ctx context.Context, request CreateAcmeAccountRequestObject) (CreateAcmeAccountResponseObject, error)
	// Delete an ACME account
	// (DELETE /orgs/{orgId}/acme-accounts/{id})
	DeleteAcmeAccount(ctx context.Context, request DeleteAcmeAccountRequestObject) (DeleteAcmeAccountResponseObject, error)
	// Get an ACME account
	// (GET /orgs/{orgId}/acme-accounts/{id})
	GetAcmeAccount(ctx context.Context, request GetAcmeAccountRequestObject) (GetAcmeAccountResponseObject, error)
	// List ACME CAs
	// (GET /orgs/{orgId}/cas)
	ListCas(ctx context.Context, request ListCasRequestObject) (ListCasResponseObject, error)
	// Add an ACME CA
	// (POST /orgs/{orgId}/cas)
	CreateCa(ctx context.Context, request CreateCaRequestObject) (CreateCaResponseObject, error)
	// Delete a CA
	// (DELETE /orgs/{orgId}/cas/{id})
	DeleteCa(ctx context.Context, request DeleteCaRequestObject) (DeleteCaResponseObject, error)
	// Get a CA
	// (GET /orgs/{orgId}/cas/{id})
	GetCa(ctx context.Context, request GetCaRequestObject) (GetCaResponseObject, error)
	// Replace a CA
	// (PUT /orgs/{orgId}/cas/{id})
	UpdateCa(ctx context.Context, request UpdateCaRequestObject) (UpdateCaResponseObject, error)
	// List certificates
	// (GET /orgs/{orgId}/certificates)
	ListCertificates(ctx context.Context, request ListCertificatesRequestObject) (ListCertificatesResponseObject, error)
	// Create a certificate
	// (POST /orgs/{orgId}/certificates)
	CreateCertificate(ctx context.Context, request CreateCertificateRequestObject) (CreateCertificateResponseObject, error)
	// Delete a certificate
	// (DELETE /orgs/{orgId}/certificates/{id})
	DeleteCertificate(ctx context.Context, request DeleteCertificateRequestObject) (DeleteCertificateResponseObject, error)
	// Get a certificate
	// (GET /orgs/{orgId}/certificates/{id})
	GetCertificate(ctx context.Context, request GetCertificateRequestObject) (GetCertificateResponseObject, error)
	// Replace a certificate definition
	// (PUT /orgs/{orgId}/certificates/{id})
	UpdateCertificate(ctx context.Context, request UpdateCertificateRequestObject) (UpdateCertificateResponseObject, error)
	// List issuance attempts
	// (GET /orgs/{orgId}/certificates/{id}/attempts)
	ListIssuanceAttempts(ctx context.Context, request ListIssuanceAttemptsRequestObject) (ListIssuanceAttemptsResponseObject, error)
	// List pending manual TXT records
	// (GET /orgs/{orgId}/certificates/{id}/manual-dns)
	ListManualDNS(ctx context.Context, request ListManualDNSRequestObject) (ListManualDNSResponseObject, error)
	// Confirm manual TXT records
	// (POST /orgs/{orgId}/certificates/{id}/manual-dns/confirm)
	ConfirmManualDNS(ctx context.Context, request ConfirmManualDNSRequestObject) (ConfirmManualDNSResponseObject, error)
	// Issue now
	// (POST /orgs/{orgId}/certificates/{id}/renew)
	RenewCertificate(ctx context.Context, request RenewCertificateRequestObject) (RenewCertificateResponseObject, error)
	// List versions
	// (GET /orgs/{orgId}/certificates/{id}/versions)
	ListCertificateVersions(ctx context.Context, request ListCertificateVersionsRequestObject) (ListCertificateVersionsResponseObject, error)
	// Download a version
	// (GET /orgs/{orgId}/certificates/{id}/versions/{vid}/download)
	DownloadCertificateVersion(ctx context.Context, request DownloadCertificateVersionRequestObject) (DownloadCertificateVersionResponseObject, error)
	// List DNS credentials
	// (GET /orgs/{orgId}/dns-credentials)
	ListDNSCredentials(ctx context.Context, request ListDNSCredentialsRequestObject) (ListDNSCredentialsResponseObject, error)
	// Add a DNS credential
	// (POST /orgs/{orgId}/dns-credentials)
	CreateDNSCredential(ctx context.Context, request CreateDNSCredentialRequestObject) (CreateDNSCredentialResponseObject, error)
	// Delete a DNS credential
	// (DELETE /orgs/{orgId}/dns-credentials/{id})
	DeleteDNSCredential(ctx context.Context, request DeleteDNSCredentialRequestObject) (DeleteDNSCredentialResponseObject, error)
	// Get a DNS credential
	// (GET /orgs/{orgId}/dns-credentials/{id})
	GetDNSCredential(ctx context.Context, request GetDNSCredentialRequestObject) (GetDNSCredentialResponseObject, error)
	// Replace a DNS credential
	// (PUT /orgs/{orgId}/dns-credentials/{id})
	UpdateDNSCredential(ctx context.Context, request UpdateDNSCredentialRequestObject) (UpdateDNSCredentialResponseObject, error)
	// Test a DNS credential
	// (POST /orgs/{orgId}/dns-credentials/{id}/test)
	TestDNSCredential(ctx context.Context, request TestDNSCredentialRequestObject) (TestDNSCredentialResponseObject, error)
	// Get org issuance defaults
	// (GET /orgs/{orgId}/issuance-defaults)
	GetOrgIssuanceDefaults(ctx context.Context, request GetOrgIssuanceDefaultsRequestObject) (GetOrgIssuanceDefaultsResponseObject, error)
	// Replace org issuance defaults
	// (PUT /orgs/{orgId}/issuance-defaults)
	PutOrgIssuanceDefaults(ctx context.Context, request PutOrgIssuanceDefaultsRequestObject) (PutOrgIssuanceDefaultsResponseObject, error)
	// Get effective org defaults
	// (GET /orgs/{orgId}/issuance-defaults/effective)
	GetEffectiveIssuanceDefaults(ctx context.Context, request GetEffectiveIssuanceDefaultsRequestObject) (GetEffectiveIssuanceDefaultsResponseObject, error)
	// List role bindings
	// (GET /role-bindings)
	ListRoleBindings(ctx context.Context, request ListRoleBindingsRequestObject) (ListRoleBindingsResponseObject, error)
	// Create a role binding
	// (POST /role-bindings)
	CreateRoleBinding(ctx context.Context, request CreateRoleBindingRequestObject) (CreateRoleBindingResponseObject, error)
	// Delete a role binding
	// (DELETE /role-bindings/{id})
	DeleteRoleBinding(ctx context.Context, request DeleteRoleBindingRequestObject) (DeleteRoleBindingResponseObject, error)
	// Test an OIDC issuer
	// (POST /settings/authentication/test)
	TestAuthentication(ctx context.Context, request TestAuthenticationRequestObject) (TestAuthenticationResponseObject, error)
	// Read a settings section
	// (GET /settings/{section})
	GetSettingsSection(ctx context.Context, request GetSettingsSectionRequestObject) (GetSettingsSectionResponseObject, error)
	// Replace a settings section
	// (PUT /settings/{section})
	PutSettingsSection(ctx context.Context, request PutSettingsSectionRequestObject) (PutSettingsSectionResponseObject, error)
	// Complete first-run setup
	// (POST /setup/complete)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
	// First-run status
	// (GET /setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// List users
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// Enable or disable a user
	// (PATCH /users/{id})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

